@abstractmethod
def fit(self, split: Split) -> None:
    """Train on the training sequences of `split`.

    Args:
        split: The dataset split to train on.
    """

@abstractmethod
def score_all(self, histories: Sequence[History]) -> torch.Tensor:
    """Score every item for every history.

    Returns:
        A `(len(histories), n_items)` tensor; higher is better.
    """

@property
def url(self) -> str:
    return _BASE_URL + self.name

def __post_init__(self) -> None:
    short = sum(len(s) < 3 for s in self.sequences)
    if short:
        raise ValueError(f"{short} users have fewer than 3 items")

@property
def n_users(self) -> int:
    return len(self.users)

@property
def n_items(self) -> int:
    return len(self.items)

@property
def n_interactions(self) -> int:
    return sum(map(len, self.sequences))

def train(self) -> list[tuple[int, ...]]:
    """Training sequences: everything but the last two items."""
    return [s[:-2] for s in self.sequences]

def valid(self) -> tuple[list[tuple[int, ...]], list[int]]:
    """Validation cases: (history without the last two items, second to last)."""
    return [s[:-2] for s in self.sequences], [s[-2] for s in self.sequences]

def test(self) -> tuple[list[tuple[int, ...]], list[int]]:
    """Test cases: (history without the last item, last item)."""
    return [s[:-1] for s in self.sequences], [s[-1] for s in self.sequences]

def __init__(self, config: PopularityConfig | None = None) -> None:
    self.config = config or PopularityConfig()
    self._scores: torch.Tensor | None = None

def score_all(self, histories: Sequence[History]) -> torch.Tensor:
    """Return the same popularity scores for every history.

    Raises:
        RuntimeError: If `fit` has not been called.
    """
    if self._scores is None:
        raise RuntimeError("call fit() before scoring")
    return self._scores.expand(len(histories), -1)

def __init__(
    self, config: SASRecConfig | None = None, device: str | None = None
) -> None:
    self.config = config or SASRecConfig()
    self.device = torch.device(
        device or ("mps" if torch.backends.mps.is_available() else "cpu")
    )
    self.net: SASRecNet | None = None
    self.history: list[dict[str, float]] = []

@timed
def fit(self, split: Split) -> None:
    """Train on `split.train()`, choosing the epoch by validation NDCG@10."""
    with seeded(self.config.seed):
        self._train(split)

def score(self, hidden: torch.Tensor, items: torch.Tensor) -> torch.Tensor:
    """Dot product of each hidden state with its item's embedding."""
    emb: torch.Tensor = self.item_emb(items)
    return (hidden * emb).sum(-1)

@classmethod
def get(cls, name: str) -> type:
    """Return the model class registered under `name`.

    Raises:
        KeyError: If no model has that name. The message lists the names
            that are registered.
    """
    try:
        return cls._registry[name]
    except KeyError:
        known = ", ".join(sorted(cls._registry)) or "none"
        raise KeyError(f"no model named {name!r}; registered: {known}") from None

@classmethod
def names(cls) -> list[str]:
    """Return the registered model names in alphabetical order."""
    return sorted(cls._registry)

@classmethod
def registry(cls) -> MappingProxyType[str, type]:
    """Return a read-only view of the registry."""
    return MappingProxyType(cls._registry)

def to_dict(self) -> dict[str, Any]:
    """Return the log as JSON-ready data (copies, not the live lists)."""
    return {
        "models": [dict(m, config=dict(m["config"])) for m in self.models],
        "timings": {label: list(s) for label, s in self.timings.items()},
        "results": {part: dict(s) for part, s in self.results.items()},
    }

def __enter__(self) -> Self:
    if self._token is not None:
        raise RuntimeError("this RunLog is already active")
    self._token = _active.set(self)
    return self
